        || !id_client || !strlen(id_client)) return (NULL);
    while (db->clients) {
        if (strcmp(db->clients->id, id_client) == 0) {
            strcpy(new_element->id, id_team);
            new_element->next = db->clients->team;
            db->clients->team = new_element;
