bool save_clients(void)
{
    data_base_t *db = get_data_base();
    client_t *save = db->clients;
    int size = 0;
    char size_str[30] = {0};
    int fd = open("./.data_base/save_file_clients.txt", O_CREAT, S_IRUSR |
